  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PERCENT = 100;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

// eslint-disable-next-line @typescript-eslint/no-unused-vars -- customer history not yet used
export function quote(customer: Customer, items: Item[]): number {
  const basePremium = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const firstInsuranceSurcharge = (basePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / PERCENT;
  return Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
}

