import { describe, expect, it } from "vitest";
import { quote } from "./quote.js";

describe("MHPCO Claim Office", () => {
  // --- Simplest case: processing fee only ---
  it("quote with an empty item list -- premium 5 G (processing fee only)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [])).toBe(5);
  });

  // --- Price list: base premium per main item type (each entry independently specified) ---
  it("quote for a single plain sword -- premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(115);
  });
  it("quote for a single plain amulet -- premium 71 G (60 base + 6 first insurance + 5 fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }])).toBe(71);
  });
  it("quote for a single plain staff -- premium 93 G (80 base + 8 first insurance + 5 fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }])).toBe(93);
  });
  it("quote for a single plain potion -- premium 49 G (40 base + 4 first insurance + 5 fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }])).toBe(49);
  });

  // --- Price list: components at 25 G base premium each ---
  it("quote for a single rune -- premium 33 G (25 base + 2.5 first insurance = 27.5, rounded up + 5 fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }])).toBe(33);
  });
  it("quote for a single moonstone -- premium 33 G (25 base, same component price as a rune)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "moonstone" }])).toBe(33);
  });

  // --- Building block of 3 alike components (base-premium examples from the spec) ---
  it.todo("base premium for 2 runes -- 50 G (no block)");
  it.todo("base premium for 3 runes -- 60 G (block applies)");
  it.todo("base premium for 4 runes -- 100 G (no block -- block requires exactly 3)");
  it.todo("base premium for 7 runes -- 175 G (no block at 7 components)");

  // --- 'Alike' means same component type (clarifying question) ---
  it.todo("base premium for 2 runes + 1 moonstone -- 75 G (no block: different types)");
  it.todo("base premium for 3 runes + 3 moonstones -- 120 G (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("cursed sword adds a 50 % surcharge on that item's base premium -- 100 -> 150 G base");
  it.todo("sword with enchantment 5 adds the 30 % high-enchantment surcharge -- 100 -> 130 G base");
  it.todo("sword with enchantment 4 gets no high-enchantment surcharge -- base stays 100 G");
  it.todo("cursed sword with enchantment 5 gets both surcharges -- 100 -> 180 G base");

  // --- Modifier scope on multi-item policies (clarifying question) ---
  it.todo("cursed sword + plain amulet -- item surcharge is 50 G (50 % of the cursed item only), policy base 210 G");

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
  it.todo("customer with 1 year with MHPCO receives no loyalty discount");
  it.todo("first insurance adds a 10 % surcharge on the policy base premium");
  it.todo("each contract after the customer's first receives a 15 % follow-up discount");
  it.todo("the customer's first quote in a scenario receives no follow-up discount");
  it.todo("the first insurance surcharge applies to every quote regardless of customer history (clarifying question)");
  it.todo("a 5 G processing fee is added at the very end of every premium");

  // --- Rounding in the MHPCO's favour ---
  it.todo("a premium of 197.5 G is rounded up to 198 G");
  it.todo("a payout of 350.5 G is rounded down to 350 G");
  it.todo("intermediate amounts stay fractional -- only the final premium is rounded");

  // --- Integration examples from the spec ---
  it.todo("newcomer (0 years, first contract) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("3-year customer's second quote, cursed steel sword enchantment 7 -- premium 160 G");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("claim on a regular steel sword enchantment 3 with damage 500 G -- payout 400 G");
  it.todo("claim on a rune (no enchantment, no material) with damage 200 G -- payout 100 G");
  it.todo("damage to an amulet with damage 300 G -- payout 200 G (deductible applies to any item type)");

  // --- Claim: special clauses ---
  it.todo("steel sword enchantment 9, damage 1000 G -- payout 400 G (50 % clause, then deductible)");
  it.todo("sword enchantment 8 exactly triggers the 50 % clause -- dragon sword, damage 1000 G -> payout 400 G");
  it.todo("dragon-material sword enchantment 5, damage 800 G -- payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword enchantment 9, damage 1000 G -- payout 400 G (50 % clause wins, then deductible)");
  it.todo("sword enchantment 7 (below threshold), steel, damage 1000 G -- payout 900 G (no special clause)");

  // --- Claim: deductible per damage event ---
  it.todo("one incident damaging a sword (500 G) and an amulet (300 G) -- payout 600 G (deductible per damaged item)");

  // --- Claim: insurance sum and cap ---
  it.todo("policy over a sword and an amulet -- insurance sum 1600 G, cap 3200 G");
  it.todo("policy over two swords -- insurance sum 2000 G, cap 4000 G");
  it.todo("policy over a sword and 3 runes -- insurance sum 1750 G (block discount affects the premium only)");
  it.todo("cursed sword with premium modifiers -- cap stays 2000 G (based on the unmodified insurance value)");
  it.todo("insurance sum for a single staff -- cap 1600 G (staff insurance value 800 G)");
  it.todo("insurance sum for a single potion -- cap 800 G (potion insurance value 400 G)");
  it.todo("insurance sum for a single moonstone -- cap 500 G (component insurance value 250 G)");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("sword policy (cap 2000 G), first claim of 1500 G -- payout 1400 G, remainingCap 600 G");
  it.todo("sword policy, second successive claim of 1500 G -- payout 600 G, remainingCap 0 G (capped)");

  // --- Claim: two damages of the same item type ---
  it.todo("two swords insured, incident damages both -- each damage entry gets its own deductible");

  // --- Error cases (observable contract: CLI exits non-zero and writes a description to stderr) ---
  it.todo("quote with an unknown item type 'broomstick' -- CLI exits non-zero, error on stderr, no results on stdout");
  it.todo("claim naming an item not covered by the policy (amulet damaged, only a sword insured) -- CLI exits non-zero with stderr description");
  it.todo("claim naming an unknown item type in a damage entry -- CLI exits non-zero with stderr description");
  it.todo("claim with more damage entries of a type than insured (two sword damages, one sword insured) -- CLI exits non-zero with stderr description");
  it.todo("claim with a negative damage amount (-200) -- CLI exits non-zero with stderr description");

  // --- CLI adapter ---
  it.todo("CLI reads the scenario JSON from stdin and writes {results: [...]} to stdout in step order");
  it.todo("CLI schema example: 5-year customer quotes an amulet then claims 200 G -- premium and payout/remainingCap results");
});

