export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PERCENT = 100;

const COMPONENT_BASE_PREMIUM = 25;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: COMPONENT_BASE_PREMIUM,
  moonstone: COMPONENT_BASE_PREMIUM,
};

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

function alikeGroupBasePremium(type: string, count: number): number {
  const qualifiesForBlock = count === BLOCK_SIZE;
  return qualifiesForBlock ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
}

export function basePremium(items: Item[]): number {
  let total = 0;
  for (const [type, count] of countByType(items)) {
    total += alikeGroupBasePremium(type, count);
  }
  return total;
}

export function quote(customer: Customer, items: Item[]): number {
  const base = basePremium(items);
  const firstInsuranceSurcharge = (base * FIRST_INSURANCE_SURCHARGE_PERCENT) / PERCENT;
  return Math.ceil(base + firstInsuranceSurcharge + PROCESSING_FEE);
}

