export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Policy {
  items: Item[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export function openPolicy(items: Item[]): Policy {
  return { items };
}

const DEDUCTIBLE = 100;
const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;

const DRAGON_MATERIAL = "dragon";
const FULL_REIMBURSEMENT_RATE = 1;

function reimbursementRate(item: Item): number {
  // The 50 % rule wins where both clauses apply.
  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD) {
    return HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
  }
  if (item.material === DRAGON_MATERIAL) {
    return FULL_REIMBURSEMENT_RATE;
  }
  return FULL_REIMBURSEMENT_RATE;
}

function payoutForDamage(damage: Damage, item: Item): number {
  return damage.amount * reimbursementRate(item) - DEDUCTIBLE;
}

export function claim(policy: Policy, incident: Incident): ClaimResult {
  const payout = incident.damages.reduce((sum, damage) => {
    const item = policy.items.find((candidate) => candidate.type === damage.itemType);
    return sum + payoutForDamage(damage, item as Item);
  }, 0);
  return { payout, remainingCap: 0 };
}

